#!/usr/bin/env python3
"""Compiled Pyodide snapshot of workflow #37 ('Gold & Silver Price Report').

Generated by skill genesis (L1 compiled/pyodide). The graph below is FROZEN
at promotion time — later edits to the workflow do not apply; re-promote to
refresh. Runs fully in the browser: /chat for agent turns, the Pyodide
worker pool for skill tool calls.
"""

import argparse
import asyncio
import json
import sys

import js
from js import window
from pyodide.ffi import to_js
from pyodide.http import pyfetch

GRAPH = json.loads("{\"workflow_id\":37,\"name\":\"Gold & Silver Price Report\",\"nodes\":[{\"id\":\"1964\",\"type\":\"start\",\"name\":\"\",\"provider\":\"\",\"model\":\"\",\"instructions\":\"\",\"skill\":\"\",\"max_tokens\":null,\"temperature\":null,\"tools\":null},{\"id\":\"1965\",\"type\":\"agent\",\"name\":\"Metals Market Researcher\",\"provider\":\"kimi\",\"model\":\"\",\"instructions\":\"You are a precious metals market researcher. Your job is to collect and analyze the latest news about gold and silver prices, market trends, mining activity, and economic factors affecting precious metals. Use the metals news tools to gather comprehensive market intelligence. Search specifically for 'gold prices' and 'silver prices' to get targeted information. Focus on: current price movements, geopolitical factors, economic indicators, mining industry activity, supply and demand dynamics, and investment trends. Organize your findings clearly with specific data points, dates, and sources. Extract any specific price levels, percentage changes, and trend information mentioned in the news.\",\"skill\":\"\",\"max_tokens\":4096,\"temperature\":0.7,\"tools\":[\"mcp_get_all_metals_news\",\"mcp_search_metals_news\"]},{\"id\":\"1966\",\"type\":\"agent\",\"name\":\"Financial News Researcher\",\"provider\":\"deepseek\",\"model\":\"\",\"instructions\":\"You are a financial markets researcher focusing on macroeconomic factors that affect precious metals. Gather financial news with themes 'gold', 'inflation', 'federal reserve', and 'dollar' to understand the economic context. Focus on: Federal Reserve policy, interest rates, inflation data, currency movements (especially USD), economic indicators, and global financial market trends. Identify how these factors influence gold and silver prices. Provide context on the broader economic environment affecting precious metals. Note any specific economic data releases or policy decisions that impact precious metals.\",\"skill\":\"\",\"max_tokens\":4096,\"temperature\":0.7,\"tools\":[\"mcp_get_financial_news\"]},{\"id\":\"1967\",\"type\":\"agent\",\"name\":\"Report Compiler\",\"provider\":\"anthropic\",\"model\":\"\",\"instructions\":\"You are a financial report writer specializing in precious metals markets. Synthesize the research from the metals researcher and financial researcher into a comprehensive, professional report on gold and silver prices. Structure the report with: Executive Summary, Current Market Overview, Price Analysis (with specific levels and trends from news sources), Key Market Drivers (geopolitical, economic, supply/demand), Industry Activity (mining, M&A, production), Market Outlook, and Investment Considerations. Use clear headings, bullet points for key facts, and maintain a professional yet accessible tone. Integrate data and insights from all sources into a cohesive narrative. Include specific price data, percentage changes, and trend information gathered from the news sources.\",\"skill\":\"\",\"max_tokens\":8192,\"temperature\":0.7,\"tools\":null},{\"id\":\"1968\",\"type\":\"output\",\"name\":\"\",\"provider\":\"\",\"model\":\"\",\"instructions\":\"\",\"skill\":\"\",\"max_tokens\":null,\"temperature\":null,\"tools\":null}],\"edges\":[[\"1964\",\"1965\"],[\"1964\",\"1966\"],[\"1965\",\"1967\"],[\"1966\",\"1967\"],[\"1967\",\"1968\"]]}")
SKILL_SCRIPTS = json.loads("{}")
SKILL_NAME = "gold-silver-price-report"
MAX_ROUNDS = 8
TRIM = 4000


def _api(path):
    base = "/gpt/backend/api/v1"
    try:
        cfg = getattr(window, "APP_CONFIG", None)
        if cfg is not None and getattr(cfg, "API_BASE_URL", None):
            base = str(cfg.API_BASE_URL)
    except Exception:
        pass
    return base.rstrip("/") + path


async def _post_chat(body):
    resp = await pyfetch(
        _api("/chat"),
        method="POST",
        headers={
            "Content-Type": "application/json",
            "Authorization": "Bearer " + str(window.authManager.token),
        },
        body=json.dumps(body),
    )
    return json.loads(await resp.string())


async def _run_skill(inp, node):
    """Nested run_skill_script → the worker pool (parallel-safe, off the
    main runtime this snapshot occupies)."""
    chat_app = getattr(window, "chatApp", None)
    if chat_app is None or not hasattr(chat_app, "_runViaPool"):
        return {"success": False,
                "error": "skill bridge unavailable (snapshot must run on the main thread)"}
    dir_name = (inp.get("dir_name") or node.get("skill") or "").strip()
    req = {
        "dirName": dir_name,
        "script": inp.get("script"),
        "argv": inp.get("argv") or [],
        "inputFiles": inp.get("input_files") or None,
        "readOutputs": inp.get("read_outputs") or None,
    }
    try:
        res = await chat_app._runViaPool(to_js(req, dict_converter=js.Object.fromEntries))
        py = res.to_py() if hasattr(res, "to_py") else res
        outs = {}
        for k, v in (py.get("outputs") or {}).items():
            outs[k] = v[:TRIM] if isinstance(v, str) else "[binary output]"
        return {
            "success": (py.get("exitCode") or 0) == 0,
            "output": {
                "exit_code": py.get("exitCode") or 0,
                "stdout": (py.get("stdout") or "")[:TRIM],
                "log_messages": (py.get("stderr") or "")[:TRIM],
                "outputs": outs,
            },
        }
    except Exception as e:
        return {"success": False, "error": str(e)[:500]}


async def _run_agent(node, context):
    """One agent node = one /chat conversation, looping tool rounds until
    the model returns final text (mirrors the browser engine's chat-unit)."""
    body_base = {
        "provider": node.get("provider") or "openai",
        "streaming": False,
        "verification_enabled": False,
        "compare_enabled": False,
    }
    if node.get("model"):
        body_base["model"] = node["model"]
    # Node instructions go in as the SYSTEM PROMPT (full authority) — same
    # as the browser engine — not concatenated into the user message.
    instructions = (node.get("instructions") or "").strip()
    if instructions:
        body_base["system_prompt"] = instructions
    if node.get("max_tokens"):
        body_base["max_tokens"] = node["max_tokens"]
    if node.get("temperature") is not None:
        body_base["temperature"] = node["temperature"]
    if node.get("tools"):
        body_base["tools"] = node["tools"]
    if node.get("skill"):
        body_base["skill_metadata"] = {
            "dir_name": node["skill"],
            "scripts": SKILL_SCRIPTS.get(node["skill"]) or ["scripts/run.py"],
        }
    message = context
    history = []
    for _ in range(MAX_ROUNDS):
        body = dict(body_base)
        body["message"] = message
        body["conversation_history"] = history
        r = await _post_chat(body)
        if r.get("success") is False:
            return "Error: " + str(r.get("error") or "chat call failed")[:400]
        if r.get("pending_client_tool_call"):
            calls = r.get("pending_tool_calls") or []
            if message:
                history.append({"role": "user", "content": message})
            history.append({
                "role": "assistant",
                "content": r.get("text") or "",
                "tool_calls": [
                    {"id": c.get("id"), "name": c.get("name"), "input": c.get("input") or {}}
                    for c in calls
                ],
            })
            for c in calls:
                result = await _run_skill(c.get("input") or {}, node)
                history.append({
                    "role": "tool",
                    "tool_call_id": c.get("id"),
                    "name": c.get("name") or "run_skill_script",
                    "content": json.dumps(result),
                })
            message = ""
            continue
        return r.get("text") or ""
    return "(node exceeded the tool-round limit)"


async def _run_graph(prompt):
    nodes = {n["id"]: n for n in GRAPH["nodes"]}
    incoming = {nid: [e[0] for e in GRAPH["edges"] if e[1] == nid] for nid in nodes}
    outputs = {}
    done = set()
    for n in GRAPH["nodes"]:
        if n["type"] == "start":
            outputs[n["id"]] = prompt
            done.add(n["id"])
    remaining = set(nodes) - done
    while remaining:
        ready = [nid for nid in remaining if all(u in done for u in incoming[nid])]
        if not ready:
            break  # cycle or orphan
        async def _run_one(nid):
            n = nodes[nid]
            parts = []
            raws = []
            for u in incoming[nid]:
                o = outputs.get(u, "")
                if not o:
                    continue
                raws.append(o)
                parts.append(o if nodes[u]["type"] == "start"
                             else "## " + (nodes[u].get("name") or u) + "\n" + o)
            ctx = "\n\n".join(parts) or prompt
            if n["type"] == "output":
                # Single feeder → pass the document through RAW (no fan-in
                # label header polluting the final HTML/Markdown).
                outputs[nid] = raws[0] if len(raws) == 1 else ctx
            else:
                outputs[nid] = await _run_agent(n, ctx)
        await asyncio.gather(*[_run_one(nid) for nid in ready])
        for nid in ready:
            done.add(nid)
            remaining.discard(nid)
    out_id = next((n["id"] for n in GRAPH["nodes"] if n["type"] == "output"), None)
    return outputs.get(out_id) or json.dumps(
        {nodes[k].get("name") or k: v for k, v in outputs.items()}, ensure_ascii=False)


def _looks_html(text):
    s = text.lstrip().lower()
    return s.startswith("<!doctype") or s.startswith("<html")


def main():
    ap = argparse.ArgumentParser(description="Run the compiled workflow snapshot.")
    ap.add_argument("--prompt", required=True,
                    help="Full plain-language instruction for the workflow run")
    args = ap.parse_args()
    final = asyncio.run(_run_graph(args.prompt))
    text = final if isinstance(final, str) else str(final)

    # Persist the workflow's OUTPUT DOCUMENT to /outputs/ and announce it
    # with a "wrote <path>" line: the platform reads announced files back
    # into the tool result and renders HTML/Markdown in the document pane —
    # the user sees the real document, not just the model's summary of it.
    import time as _time
    ext = "html" if _looks_html(text) else "md"
    out_path = "/outputs/%s_%s.%s" % (SKILL_NAME, _time.strftime("%Y-%m-%d_%H%M%S"), ext)
    try:
        with open(out_path, "w", encoding="utf-8") as f:
            f.write(text)
        print("wrote %s" % out_path)
    except Exception as e:
        print("could not write output document: %s" % e, file=sys.stderr)

    head = text[:1500]
    print(head)
    if len(text) > 1500:
        print("...[document continues — the full version is rendered for the user "
              "from %s; do NOT re-paste it]" % out_path)


if __name__ == "__main__":
    main()
